<template>
	<Dialog
		v-model="show"
		:options="{
			title: __('New Batch'),
			size: '3xl',
		}"
	>
		<template #body-content>
			<div class="text-base">
				<div class="grid grid-cols-3 gap-5">
					<FormControl
						v-model="batch.title"
						:label="__('Title')"
						:required="true"
						autocomplete="off"
					/>
					<FormControl
						v-model="batch.start_date"
						:label="__('Start Date')"
						type="date"
						:required="true"
					/>
					<FormControl
						v-model="batch.end_date"
						:label="__('End Date')"
						type="date"
						:required="true"
					/>
					<FormControl
						v-model="batch.start_time"
						:label="__('Start Time')"
						type="time"
						:required="true"
					/>
					<FormControl
						v-model="batch.end_time"
						:label="__('End Time')"
						type="time"
						:required="true"
					/>
					<FormControl
						v-model="batch.timezone"
						:label="__('Timezone')"
						:required="true"
						autocomplete="off"
					/>
					<Link
						v-model="batch.category"
						doctype="LMS Category"
						:label="__('Category')"
						:onCreate="createCategory"
					/>
					<FormControl
						v-model="batch.seat_count"
						:label="__('Seat Count')"
						type="number"
						:required="false"
					/>
					<FormControl
						v-model="batch.medium"
						type="select"
						:options="mediumOptions"
						:label="__('Medium')"
						class="mb-4"
					/>
				</div>

				<div class="space-y-5 border-t mt-5 pt-5">
					<div class="grid grid-cols-2 gap-5">
						<FormControl
							v-model="batch.description"
							:label="__('Description')"
							type="textarea"
							:required="true"
							:rows="4"
						/>
						<MultiSelect
							v-model="batch.instructors"
							doctype="User"
							:label="__('Instructors')"
							:required="true"
							:onCreate="() => (showMemberModal = true)"
							url="lms.lms.api.search_users_by_role"
							:searchParams="{ roles: JSON.stringify(['Batch Evaluator']) }"
						/>
					</div>
					<div class="">
						<div class="mb-1.5 text-sm text-ink-gray-5">
							{{ __('Batch Details') }}
							<span class="text-ink-red-3">*</span>
						</div>
						<TextEditor
							:content="batch.batch_details"
							@change="(val: string) => (batch.batch_details = val)"
							:editable="true"
							:fixedMenu="true"
							editorClass="prose-sm max-w-none border-b border-x bg-surface-gray-2 rounded-b-md py-1 px-2 min-h-[10rem] max-h-[14rem] overflow-auto"
						/>
					</div>
				</div>
			</div>
		</template>
		<template #actions="{ close }">
			<div class="text-right">
				<Button variant="solid" @click="saveBatch(close)">
					{{ __('Save') }}
				</Button>
			</div>
		</template>
	</Dialog>
	<NewMemberModal
		v-model="showMemberModal"
		:defaultRoles="['batch_evaluator']"
		@created="onInstructorCreated"
	/>
</template>
<script setup lang="ts">
import { Button, Dialog, FormControl, TextEditor, toast } from 'frappe-ui'
import { useOnboarding, useTelemetry } from 'frappe-ui/frappe'
import { computed, inject, onMounted, onBeforeUnmount, ref } from 'vue'
import { useRouter } from 'vue-router'
import { sanitizeHTML, createLMSCategory } from '@/utils'
import MultiSelect from '@/components/Controls/MultiSelect.vue'
import Link from '@/components/Controls/Link.vue'
import NewMemberModal from '@/components/Modals/NewMemberModal.vue'

const show = defineModel<boolean>({ required: true, default: false })
const router = useRouter()
const { capture } = useTelemetry()
const { updateOnboardingStep } = useOnboarding('learning')
const user = inject<any>('$user')
const showMemberModal = ref(false)

const props = defineProps<{
	batches: any
}>()

type Batch = {
	title: string
	start_date: string | null
	end_date: string | null
	start_time: string | null
	end_time: string | null
	timezone: string | null
	description: string
	batch_details: string
	instructors: string[]
	category: string | null
	seat_count: number
	medium: string | null
}

const batch = ref<Batch>({
	title: '',
	start_date: null,
	end_date: null,
	start_time: null,
	end_time: null,
	timezone: null,
	description: '',
	batch_details: '',
	instructors: [],
	category: null,
	seat_count: 0,
	medium: null,
})

const createCategory = (name: string, done: () => void) => {
	createLMSCategory(name).then((categoryName: string) => {
		if (!categoryName) return
		batch.value.category = categoryName
		done()
	})
}

const onInstructorCreated = (user: any) => {
	batch.value.instructors = [...batch.value.instructors, user.name]
}

const validateFields = () => {
	Object.keys(batch.value).forEach((key) => {
		if (typeof batch.value[key as keyof Batch] === 'string') {
			batch.value[key as keyof Batch] = sanitizeHTML(
				batch.value[key as keyof Batch] as string
			)
		}
	})
}

const saveBatch = (close: () => void = () => {}) => {
	validateFields()
	props.batches.insert.submit(
		{
			...batch.value,
			instructors: batch.value.instructors.map((instructor) => ({
				instructor: instructor,
			})),
		},
		{
			onSuccess(data: any) {
				toast.success(__('Batch created successfully'))
				close()
				capture('batch_created')
				router.push({
					name: 'BatchDetail',
					params: { batchName: data.name },
					hash: '#settings',
				})
				if (user.data?.is_system_manager) {
					updateOnboardingStep('create_first_batch', true, false, () => {
						localStorage.setItem('firstBatch', data.name)
					})
				}
			},
			onError(err: any) {
				toast.error(cleanError(err.messages?.[0]))
				console.error(err)
			},
		}
	)
}

const keyboardShortcut = (e: KeyboardEvent) => {
	if (
		e.key === 's' &&
		(e.ctrlKey || e.metaKey) &&
		e.target &&
		e.target instanceof HTMLElement &&
		!e.target.classList.contains('ProseMirror')
	) {
		saveBatch()
		e.preventDefault()
	}
}

onMounted(() => {
	window.addEventListener('keydown', keyboardShortcut)
	capture('batch_form_opened')
})

onBeforeUnmount(() => {
	window.removeEventListener('keydown', keyboardShortcut)
	capture('batch_form_closed', {
		data: batch.value,
	})
})

const mediumOptions = computed(() => {
	return [
		{
			label: __('Online'),
			value: 'Online',
		},
		{
			label: __('Offline'),
			value: 'Offline',
		},
	]
})
</script>
